// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
  // This is an internal method for creating notifications, not exposed in the interface
  // create(userId: string, message: string): Notification;
}

import { EventEmitter } from "events";
import { IEventBus } from "./types";

export class EventBus implements IEventBus {
  private emitter = new EventEmitter();

  publish(event: string, payload: unknown): void {
    this.emitter.emit(event, payload);
  }

  subscribe(event: string, callback: (payload: unknown) => void): void {
    this.emitter.on(event, callback);
  }
}

import { randomUUID } from "crypto";
import { User, IUserService } from "./types";

export class UserService implements IUserService {
  private users = new Map<string, User>();

  create(input: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = {
      id,
      ...input,
    };
    this.users.set(id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.users.get(id);
    if (!user) {
      throw new Error(`User with id ${id} not found`);
    }
    return user;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    const updatedUser = { ...user, ...input };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  delete(id: string): void {
    if (!this.users.has(id)) {
      throw new Error(`User with id ${id} not found`);
    }
    this.users.delete(id);
  }
}

import { randomUUID } from "crypto";
import { Project, IProjectService } from "../types";

export class ProjectService implements IProjectService {
  private projects = new Map<string, Project>();

  // Note: We are not validating if the user exists here as per architectural rule #1.
  // The router or a higher-level component is responsible for that.

  create(input: { name: string; description: string }): Project {
    const id = randomUUID();
    const project: Project = {
      id,
      ...input,
      memberIds: [],
    };
    this.projects.set(id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.projects.get(id);
    if (!project) {
      throw new Error(`Project with id ${id} not found`);
    }
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const project = this.getById(id);
    const updatedProject = { ...project, ...input };
    this.projects.set(id, updatedProject);
    return updatedProject;
  }

  delete(id: string): void {
    if (!this.projects.has(id)) {
      throw new Error(`Project with id ${id} not found`);
    }
    // We should also handle what happens to tasks in this project.
    // The spec doesn't mention cascading deletes, so we'll just delete the project.
    this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    if (project.memberIds.includes(userId)) {
        return project; // Or throw an error, let's just return for idempotency
    }
    project.memberIds.push(userId);
    this.projects.set(projectId, project);
    return project;
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    const memberIndex = project.memberIds.indexOf(userId);
    if (memberIndex === -1) {
        throw new Error(`User ${userId} is not a member of project ${projectId}`);
    }
    project.memberIds.splice(memberIndex, 1);
    this.projects.set(projectId, project);
    return project;
  }
}

import { randomUUID } from "crypto";
import {
  Task,
  ITaskService,
  TaskStatus,
  IEventBus,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from "../types";

export class TaskService implements ITaskService {
  private tasks = new Map<string, Task>();

  constructor(private eventBus: IEventBus) {}

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      ...input,
      status: "todo",
      assigneeId: null,
    };
    this.tasks.set(id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task with id ${id} not found`);
    }
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const task = this.getById(id);
    const updatedTask = { ...task, ...input };
    this.tasks.set(id, updatedTask);
    return updatedTask;
  }

  delete(id: string): void {
    if (!this.tasks.has(id)) {
      throw new Error(`Task with id ${id} not found`);
    }
    this.tasks.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.getById(taskId);
    task.assigneeId = assigneeId;
    this.tasks.set(taskId, task);

    const payload: TaskAssignedPayload = {
      taskId,
      taskTitle: task.title,
      assigneeId,
    };
    this.eventBus.publish("task.assigned", payload);

    return task;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.getById(taskId);
    const oldStatus = task.status;

    if (oldStatus === newStatus) {
      return task;
    }

    const allowedTransitions: Record<TaskStatus, TaskStatus[]> = {
      todo: ["in-progress"],
      "in-progress": ["done"],
      done: [],
    };

    if (!allowedTransitions[oldStatus].includes(newStatus)) {
      throw new Error(
        `Invalid status transition from ${oldStatus} to ${newStatus}`
      );
    }

    task.status = newStatus;
    this.tasks.set(taskId, task);

    const payload: TaskStatusChangedPayload = {
      taskId,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return task;
  }
}

import { randomUUID } from "crypto";
import {
  Comment,
  ICommentService,
  IEventBus,
  CommentAddedPayload,
  ITaskService,
  IUserService,
} from "../types";

export class CommentService implements ICommentService {
  private comments = new Map<string, Comment>();

  constructor(
    private eventBus: IEventBus,
    private taskService: ITaskService, // Injected to get task details for events
    private userService: IUserService // Injected to get user details for events
  ) {}

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const id = randomUUID();
    const comment: Comment = {
      id,
      ...input,
      createdAt: new Date().toISOString(),
    };
    this.comments.set(id, comment);

    // Enrich the event payload with details from other services
    const task = this.taskService.getById(input.taskId);
    const author = this.userService.getById(input.authorId);

    const payload: CommentAddedPayload = {
      commentId: id,
      taskId: input.taskId,
      taskTitle: task.title,
      authorId: input.authorId,
      authorName: author.name,
    };
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.comments.get(id);
    if (!comment) {
      throw new Error(`Comment with id ${id} not found`);
    }
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(
      (comment) => comment.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.comments.has(id)) {
      throw new Error(`Comment with id ${id} not found`);
    }
    this.comments.delete(id);
  }
}

import { randomUUID } from "crypto";
import {
  Notification,
  INotificationService,
  IEventBus,
  ITaskService,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
} from "../types";

export class NotificationService implements INotificationService {
  private notifications = new Map<string, Notification>();

  constructor(
    private eventBus: IEventBus,
    private taskService: ITaskService
  ) {}

  // This method is called from main.ts to set up the event listeners
  public subscribeToEvents(): void {
    this.eventBus.subscribe("task.assigned", (payload) =>
      this.handleTaskAssigned(payload as TaskAssignedPayload)
    );
    this.eventBus.subscribe("task.statusChanged", (payload) =>
      this.handleTaskStatusChanged(payload as TaskStatusChangedPayload)
    );
    this.eventBus.subscribe("comment.added", (payload) =>
      this.handleCommentAdded(payload as CommentAddedPayload)
    );
  }

  private create(userId: string, message: string): Notification {
    const id = randomUUID();
    const notification: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(id, notification);
    return notification;
  }

  private handleTaskAssigned(payload: TaskAssignedPayload): void {
    const message = `Task '${payload.taskTitle}' has been assigned to you.`;
    this.create(payload.assigneeId, message);
  }

  private handleTaskStatusChanged(payload: TaskStatusChangedPayload): void {
    if (payload.assigneeId) {
      const message = `Task '${payload.taskTitle}' status changed from ${payload.oldStatus} to ${payload.newStatus}.`;
      this.create(payload.assigneeId, message);
    }
  }

  private handleCommentAdded(payload: CommentAddedPayload): void {
    try {
      const task = this.taskService.getById(payload.taskId);
      if (task && task.assigneeId && task.assigneeId !== payload.authorId) {
        const message = `${payload.authorName} commented on your assigned task '${payload.taskTitle}'.`;
        this.create(task.assigneeId, message);
      }
    } catch (error) {
      // Task might have been deleted, or something else. Silently fail for now.
      console.error(`Error creating notification for comment: ${error}`);
    }
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values())
      .filter((n) => n.userId === userId)
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.notifications.get(notificationId);
    if (!notification) {
      throw new Error(`Notification with id ${notificationId} not found`);
    }
    notification.read = true;
    this.notifications.set(notificationId, notification);
    return notification;
  }
}

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import {
  IUserService,
  IProjectService,
  ITaskService,
  ICommentService,
  INotificationService,
} from "./types";

// Helper function to parse request body
async function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk.toString();
    });
    req.on("end", () => {
      try {
        resolve(JSON.parse(body || "{}"));
      } catch (e) {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", (err) => {
      reject(err);
    });
  });
}

// Helper to send JSON response
function sendJson(res: ServerResponse, statusCode: number, payload: any) {
  res.writeHead(statusCode, { "Content-Type": "application/json" });
  res.end(JSON.stringify(payload));
}

export class ApiRouter {
  constructor(
    private userService: IUserService,
    private projectService: IProjectService,
    private taskService: ITaskService,
    private commentService: ICommentService,
    private notificationService: INotificationService
  ) {}

  public async handleRequest(req: IncomingMessage, res: ServerResponse) {
    const { method, url } = req;
    if (!url) {
      return sendJson(res, 400, { error: "URL is required" });
    }

    const parsedUrl = new URL(url, `http://${req.headers.host}`);
    const path = parsedUrl.pathname;
    const query = parsedUrl.searchParams;

    try {
        // User routes
        if (path === '/users') {
            if (method === 'GET') {
                const users = this.userService.getAll();
                sendJson(res, 200, users);
            } else if (method === 'POST') {
                const body = await parseBody(req);
                const newUser = this.userService.create(body);
                sendJson(res, 201, newUser);
            }
        } else if (path.startsWith('/users/')) {
            const id = path.split('/')[2];
            if (method === 'GET') {
                const user = this.userService.getById(id);
                sendJson(res, 200, user);
            } else if (method === 'PUT') {
                const body = await parseBody(req);
                const updatedUser = this.userService.update(id, body);
                sendJson(res, 200, updatedUser);
            } else if (method === 'DELETE') {
                this.userService.delete(id);
                res.writeHead(204).end();
            }
        }

        // Project routes
        else if (path === '/projects') {
            if (method === 'GET') {
                const projects = this.projectService.getAll();
                sendJson(res, 200, projects);
            } else if (method === 'POST') {
                const body = await parseBody(req);
                const newProject = this.projectService.create(body);
                sendJson(res, 201, newProject);
            }
        } else if (path.startsWith('/projects/')) {
            const idMatch = path.match(/^\/projects\/([^\/]+)(?:\/(.*))?$/);
            if(!idMatch) return sendJson(res, 404, { error: 'Route not found' });

            const projectId = idMatch[1];
            const remainingPath = idMatch[2];

            if(!remainingPath) {
                if(method === 'GET') {
                     const project = this.projectService.getById(projectId);
                     sendJson(res, 200, project);
                } else if (method === 'PUT') {
                    const body = await parseBody(req);
                    const updated = this.projectService.update(projectId, body);
                    sendJson(res, 200, updated);
                } else if (method === 'DELETE') {
                    this.projectService.delete(projectId);
                    res.writeHead(204).end();
                }
            } else if (remainingPath === 'members') {
                 const body = await parseBody(req);
                 const { userId } = body;
                 if(!userId) return sendJson(res, 400, { error: 'userId is required in body' });

                 // Orchestration: Check if user exists before adding
                 this.userService.getById(userId); 

                 if(method === 'POST') {
                    const updatedProject = this.projectService.addMember(projectId, userId);
                    sendJson(res, 200, updatedProject);
                 } else if (method === 'DELETE') {
                    const updatedProject = this.projectService.removeMember(projectId, userId);
                    sendJson(res, 200, updatedProject);
                 }
            }
        }

        // Task routes
        else if (path === '/tasks') {
            if(method === 'GET') {
                const projectId = query.get('projectId');
                if(!projectId) return sendJson(res, 400, {error: 'projectId query parameter is required'});
                const tasks = this.taskService.getByProject(projectId);
                sendJson(res, 200, tasks);
            } else if (method === 'POST') {
                const body = await parseBody(req);
                const newTask = this.taskService.create(body);
                sendJson(res, 201, newTask);
            }
        } else if (path.startsWith('/tasks/')) {
            const idMatch = path.match(/^\/tasks\/([^\/]+)(?:\/(.*))?$/);
            if(!idMatch) return sendJson(res, 404, { error: 'Route not found' });
            const taskId = idMatch[1];
            const remainingPath = idMatch[2];

            if(!remainingPath) {
                if(method === 'GET') {
                    const task = this.taskService.getById(taskId);
                    sendJson(res, 200, task);
                } else if (method === 'PUT') {
                    const body = await parseBody(req);
                    const updated = this.taskService.update(taskId, body);
                    sendJson(res, 200, updated);
                } else if (method === 'DELETE') {
                    this.taskService.delete(taskId);
                    res.writeHead(204).end();
                }
            } else if(remainingPath === 'status') {
                if(method === 'PUT') {
                    const body = await parseBody(req);
                    const updated = this.taskService.changeStatus(taskId, body.status);
                    sendJson(res, 200, updated);
                }
            } else if(remainingPath === 'assign') {
                if(method === 'PUT') {
                    const body = await parseBody(req);
                    // Orchestration: Check if user exists before assigning
                    this.userService.getById(body.assigneeId);
                    const updated = this.taskService.assign(taskId, body.assigneeId);
                    sendJson(res, 200, updated);
                }
            }
        }

        // Comment routes
        else if (path === '/comments') {
            if (method === 'GET') {
                const taskId = query.get('taskId');
                if (!taskId) return sendJson(res, 400, { error: 'taskId query parameter is required' });
                const comments = this.commentService.getByTask(taskId);
                sendJson(res, 200, comments);
            } else if (method === 'POST') {
                const body = await parseBody(req);
                // Orchestration: Check if author exists
                this.userService.getById(body.authorId);
                const newComment = this.commentService.create(body);
                sendJson(res, 201, newComment);
            }
        } else if (path.startsWith('/comments/')) {
            const id = path.split('/')[2];
            if (method === 'GET') {
                const comment = this.commentService.getById(id);
                sendJson(res, 200, comment);
            } else if (method === 'DELETE') {
                this.commentService.delete(id);
                res.writeHead(204).end();
            }
        }

        // Notification routes
        else if (path === '/notifications') {
             if (method === 'GET') {
                const userId = query.get('userId');
                if (!userId) return sendJson(res, 400, { error: 'userId query parameter is required' });
                const notifications = this.notificationService.getByUser(userId);
                sendJson(res, 200, notifications);
            }
        } else if (path.startsWith('/notifications/')) {
            const idMatch = path.match(/^\/notifications\/([^\/]+)\/read$/);
            if(idMatch && method === 'PUT') {
                const notificationId = idMatch[1];
                const notification = this.notificationService.markAsRead(notificationId);
                sendJson(res, 200, notification);
            }
        }

        else {
            sendJson(res, 404, { error: 'Route not found' });
        }

    } catch (error: any) {
      if (error.message.includes("not found")) {
        sendJson(res, 404, { error: error.message });
      } else if (error.message.includes("Invalid status transition")) {
        sendJson(res, 400, { error: error.message });
      } else {
        console.error(error);
        sendJson(res, 500, { error: 'Internal Server Error' });
      }
    }
  }
}

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { ApiRouter } from "./router";

const PORT = process.env.PORT || 3000;

function main() {
  // 1. Instantiate all components
  const eventBus = new EventBus();
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);

  // 2. Inject dependencies
  const commentService = new CommentService(eventBus, taskService, userService);
  const notificationService = new NotificationService(eventBus, taskService);

  // 3. Set up event subscriptions
  notificationService.subscribeToEvents();

  // 4. Instantiate the router with all services
  const router = new ApiRouter(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  // 5. Create and start the HTTP server
  const server = createServer((req, res) => {
    router.handleRequest(req, res);
  });

  server.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

main();

import { request } from 'http';

const BASE_URL = 'http://localhost:3000';

// Helper to make HTTP requests and log results
async function apiCall(method: string, path: string, body: any = null): Promise<any> {
  return new Promise((resolve, reject) => {
    console.log(`\n>> ${method} ${path}` + (body ? ` with body ${JSON.stringify(body)}` : ''));

    const options = {
      method,
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      }
    };

    const req = request(BASE_URL + path, options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        console.log(`<< ${res.statusCode} ${res.statusMessage}`);
        if (data) {
            const jsonData = JSON.parse(data);
            console.log(jsonData);
            resolve(jsonData);
        } else {
            resolve(null);
        }
      });
    });

    req.on('error', (e) => {
        console.error(`!! Request failed: ${e.message}`);
        reject(e);
    });

    if (body) {
      req.write(JSON.stringify(body));
    }
    req.end();
  });
}

// Main demo sequence
async function runDemo() {
    console.log('--- Starting API Demo ---');
    await new Promise(res => setTimeout(res, 1000)); // Wait for server to be ready

    try {
        // 1. Create users
        const user1 = await apiCall('POST', '/users', { name: 'Alice', email: 'alice@example.com' });
        const user2 = await apiCall('POST', '/users', { name: 'Bob', email: 'bob@example.com' });

        // 2. Create a project
        const project = await apiCall('POST', '/projects', { name: 'New Website', description: 'A project to build a new website.' });

        // 3. Add members to the project
        await apiCall('POST', `/projects/${project.id}/members`, { userId: user1.id });
        await apiCall('POST', `/projects/${project.id}/members`, { userId: user2.id });

        // 4. Create tasks
        const task1 = await apiCall('POST', '/tasks', { title: 'Design Homepage', description: 'Create a mockup for the new homepage.', projectId: project.id });
        const task2 = await apiCall('POST', '/tasks', { title: 'Setup Database', description: 'Setup the initial schema for Postgres.', projectId: project.id });

        // 5. Assign tasks
        await apiCall('PUT', `/tasks/${task1.id}/assign`, { assigneeId: user1.id });

        // 6. Check notifications for Alice (user1)
        await apiCall('GET', `/notifications?userId=${user1.id}`);

        // 7. Change task status
        await apiCall('PUT', `/tasks/${task1.id}/status`, { status: 'in-progress' });

        // 8. Add a comment
        const comment = await apiCall('POST', '/comments', { taskId: task1.id, authorId: user2.id, body: "How is the design coming along?" });

        // 9. Check notifications for Alice again (should have status change and comment notifications)
        const notifications = await apiCall('GET', `/notifications?userId=${user1.id}`);

        // 10. Mark a notification as read
        if (notifications && notifications.length > 0) {
            await apiCall('PUT', `/notifications/${notifications[0].id}/read`);
        }

        // Final check of Alice's notifications
        await apiCall('GET', `/notifications?userId=${user1.id}`);

        console.log('\n--- Demo Completed Successfully ---');

    } catch (error) {
        console.error('\n--- Demo Failed ---');
        console.error(error);
    } 
}

