import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import {
  IUserService,
  IProjectService,
  ITaskService,
  ICommentService,
  INotificationService,
} from "./types";

// Helper function to parse request body
async function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk.toString();
    });
    req.on("end", () => {
      if (body === "") {
        return resolve({});
      }
      try {
        resolve(JSON.parse(body));
      } catch (e) {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", (err) => {
      reject(err);
    });
  });
}

// Helper to send JSON response
function sendJson(res: ServerResponse, statusCode: number, payload: any) {
  res.writeHead(statusCode, { "Content-Type": "application/json" });
  res.end(JSON.stringify(payload));
}

export class ApiRouter {
  constructor(
    private userService: IUserService,
    private projectService: IProjectService,
    private taskService: ITaskService,
    private commentService: ICommentService,
    private notificationService: INotificationService
  ) {}

  public async handleRequest(req: IncomingMessage, res: ServerResponse) {
    const { method, url } = req;
    if (!url) {
      return sendJson(res, 400, { error: "URL is required" });
    }

    // The base is required, but not used for routing
    const parsedUrl = new URL(url, `http://${req.headers.host || 'localhost'}`);
    const path = parsedUrl.pathname;
    const query = parsedUrl.searchParams;

    try {
        if (path === '/users' && method === 'GET') {
            const users = this.userService.getAll();
            return sendJson(res, 200, users);
        }
        if (path === '/users' && method === 'POST') {
            const body = await parseBody(req);
            const newUser = this.userService.create(body);
            return sendJson(res, 201, newUser);
        }
        const userMatch = path.match(/^\/users\/([^\/]+)$/);
        if (userMatch && userMatch[1]) {
            const id = userMatch[1];
            if (method === 'GET') {
                const user = this.userService.getById(id);
                return sendJson(res, 200, user);
            }
            if (method === 'PUT') {
                const body = await parseBody(req);
                const updatedUser = this.userService.update(id, body);
                return sendJson(res, 200, updatedUser);
            }
            if (method === 'DELETE') {
                this.userService.delete(id);
                res.writeHead(204).end();
                return;
            }
        }

        if (path === '/projects' && method === 'GET') {
            const projects = this.projectService.getAll();
            return sendJson(res, 200, projects);
        }
        if (path === '/projects' && method === 'POST') {
            const body = await parseBody(req);
            const newProject = this.projectService.create(body);
            return sendJson(res, 201, newProject);
        }

        const projectMemberMatch = path.match(/^\/projects\/([^\/]+)\/members$/);
        if (projectMemberMatch && projectMemberMatch[1]) {
            const projectId = projectMemberMatch[1];
            const body = await parseBody(req);
            const { userId } = body;
            if (!userId) {
                return sendJson(res, 400, { error: 'userId is required in body' });
            }
            this.userService.getById(userId); // Validate user exists
            if (method === 'POST') {
                const updatedProject = this.projectService.addMember(projectId, userId);
                return sendJson(res, 200, updatedProject);
            }
            if (method === 'DELETE') {
                 const updatedProject = this.projectService.removeMember(projectId, userId);
                 return sendJson(res, 200, updatedProject);
            }
        }

        const projectMatch = path.match(/^\/projects\/([^\/]+)$/);
        if (projectMatch && projectMatch[1]) {
            const id = projectMatch[1];
            if (method === 'GET') {
                const project = this.projectService.getById(id);
                return sendJson(res, 200, project);
            }
            if (method === 'PUT') {
                const body = await parseBody(req);
                const updated = this.projectService.update(id, body);
                return sendJson(res, 200, updated);
            }
            if (method === 'DELETE') {
                this.projectService.delete(id);
                res.writeHead(204).end();
                return;
            }
        }

        if (path === '/tasks' && method === 'GET') {
            const projectId = query.get('projectId');
            if (!projectId) return sendJson(res, 400, {error: 'projectId query parameter is required'});
            const tasks = this.taskService.getByProject(projectId);
            return sendJson(res, 200, tasks);
        }
        if (path === '/tasks' && method === 'POST') {
            const body = await parseBody(req);
            const newTask = this.taskService.create(body);
            return sendJson(res, 201, newTask);
        }

        const taskStatusMatch = path.match(/^\/tasks\/([^\/]+)\/status$/);
        if (taskStatusMatch && taskStatusMatch[1] && method === 'PUT') {
            const taskId = taskStatusMatch[1];
            const body = await parseBody(req);
            const updated = this.taskService.changeStatus(taskId, body.status);
            return sendJson(res, 200, updated);
        }

        const taskAssignMatch = path.match(/^\/tasks\/([^\/]+)\/assign$/);
        if (taskAssignMatch && taskAssignMatch[1] && method === 'PUT') {
            const taskId = taskAssignMatch[1];
            const body = await parseBody(req);
            this.userService.getById(body.assigneeId); // Validate user
            const updated = this.taskService.assign(taskId, body.assigneeId);
            return sendJson(res, 200, updated);
        }

        const taskMatch = path.match(/^\/tasks\/([^\/]+)$/);
        if (taskMatch && taskMatch[1]) {
            const id = taskMatch[1];
            if (method === 'GET') {
                const task = this.taskService.getById(id);
                return sendJson(res, 200, task);
            }
            if (method === 'PUT') {
                const body = await parseBody(req);
                const updated = this.taskService.update(id, body);
                return sendJson(res, 200, updated);
            }
            if (method === 'DELETE') {
                this.taskService.delete(id);
                res.writeHead(204).end();
                return;
            }
        }

        if (path === '/comments' && method === 'GET') {
            const taskId = query.get('taskId');
            if (!taskId) return sendJson(res, 400, { error: 'taskId query parameter is required' });
            const comments = this.commentService.getByTask(taskId);
            return sendJson(res, 200, comments);
        }
        if (path === '/comments' && method === 'POST') {
            const body = await parseBody(req);
            this.userService.getById(body.authorId); // Validate user
            const newComment = this.commentService.create(body);
            return sendJson(res, 201, newComment);
        }

        const commentMatch = path.match(/^\/comments\/([^\/]+)$/);
        if (commentMatch && commentMatch[1]) {
            const id = commentMatch[1];
            if (method === 'GET') {
                const comment = this.commentService.getById(id);
                return sendJson(res, 200, comment);
            }
            if (method === 'DELETE') {
                this.commentService.delete(id);
                res.writeHead(204).end();
                return;
            }
        }

        const notificationReadMatch = path.match(/^\/notifications\/([^\/]+)\/read$/);
        if (notificationReadMatch && notificationReadMatch[1] && method === 'PUT') {
            const notificationId = notificationReadMatch[1];
            const notification = this.notificationService.markAsRead(notificationId);
            return sendJson(res, 200, notification);
        }

        if (path === '/notifications' && method === 'GET') {
            const userId = query.get('userId');
            if (!userId) return sendJson(res, 400, { error: 'userId query parameter is required' });
            const notifications = this.notificationService.getByUser(userId);
            return sendJson(res, 200, notifications);
        }

        return sendJson(res, 404, { error: `Route not found: ${method} ${path}` });

    } catch (error: any) {
        console.error(`[ERROR] ${error.stack}`);
        if (error.message.includes("not found")) {
            return sendJson(res, 404, { error: error.message });
        }
        if (error.message.includes("Invalid status transition") || error.message.includes("is not a member")) {
            return sendJson(res, 400, { error: error.message });
        }
        if (error.message.includes("Invalid JSON")) {
             return sendJson(res, 400, { error: error.message });
        }
        return sendJson(res, 500, { error: 'Internal Server Error' });
    }
  }
}

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { ApiRouter } from "./router";

const PORT = process.env.PORT || 3000;

function main() {
  // 1. Instantiate all components
  const eventBus = new EventBus();
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);

  // 2. Inject dependencies for services that need them
  const commentService = new CommentService(eventBus, taskService, userService);
  // Explicitly type notificationService to ensure access to class-specific methods
  const notificationService: NotificationService = new NotificationService(eventBus, taskService);

  // 3. Set up event subscriptions
  notificationService.subscribeToEvents();

  // 4. Instantiate the router with all services
  const router = new ApiRouter(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  // 5. Create and start the HTTP server
  const server = createServer((req, res) => {
    router.handleRequest(req, res);
  });

  server.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

// A simple mechanism to stop the server, useful for tests or demo scripts
if (require.main === module) {
    main();
}

