import { randomUUID } from 'node:crypto';
import {
  IEventBus,
  INotificationService,
  Notification,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
  ITaskService,
} from '../types';

export class NotificationService implements INotificationService {
  private notifications = new Map<string, Notification>();

  constructor(private eventBus: IEventBus, private taskService: ITaskService) {
    this.eventBus.subscribe('task.assigned', this.handleTaskAssigned.bind(this));
    this.eventBus.subscribe(
      'task.statusChanged',
      this.handleTaskStatusChanged.bind(this)
    );
    this.eventBus.subscribe('comment.added', this.handleCommentAdded.bind(this));
  }

  private handleTaskAssigned(payload: unknown): void {
    const { taskId, taskTitle, assigneeId } = payload as TaskAssignedPayload;
    if (assigneeId) {
      this.create({
        userId: assigneeId,
        message: `Task '${taskTitle}' assigned to you`,
      });
    }
  }

  private handleTaskStatusChanged(payload: unknown): void {
    const { taskTitle, newStatus, assigneeId } = payload as TaskStatusChangedPayload;
    if (assigneeId) {
      this.create({
        userId: assigneeId,
        message: `Task '${taskTitle}' status changed to ${newStatus}`,
      });
    }
  }

  private handleCommentAdded(payload: unknown): void {
    const { taskId, authorName } = payload as CommentAddedPayload;
    const task = this.taskService.getById(taskId);
    if (task && task.assigneeId) {
      this.create({
        userId: task.assigneeId,
        message: `New comment from ${authorName} on task '${task.title}'`,
      });
    }
  }

  create(notification: { userId: string; message: string; }): Notification {
    const id = randomUUID();
    const newNotification: Notification = {
      id,
      ...notification,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(id, newNotification);
    return newNotification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter(
      (n) => n.userId === userId && !n.read
    );
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.notifications.get(notificationId);
    if (!notification) {
      throw new Error('Notification not found');
    }
    notification.read = true;
    return notification;
  }
}

